// Records whether stop() was reached so a test can assert that a server-wide
// stop propagates to running plugins.
module.exports = function (app) {
  const plugin = {
    id: 'stoptrackingplugin',
    name: 'Stop tracking plugin',
    description: 'Records that stop() was called',
    schema: {},
    started: false,
    stopped: false,
    start: function () {
      plugin.started = true
    },
    stop: function () {
      plugin.stopped = true
    }
  }
  return plugin
}
